css:
.frame {
  padding: 12px;
  border: 2px dashed #a1a1aa;
}

.panel {
  box-sizing: border-box;
  width: 100%;
  max-width: 480px;
  margin: 0 auto;
  padding: 24px;
  background: #fed7aa;
  border: 1px solid #f97316;
  border-radius: 6px;
}

.title,
.text {
  margin: 0;
}

.title {
  font-weight: 600;
}

.text {
  margin-top: 8px;
}
